                              note: "Safer for the men, and costs time.",
                              bonus: 0,
                              bonusByPosture: {strongpointsIntact: 3, fieldDivision: 2, thinGarrison: -1},
                              meters: {initiative: -1},
                              costReason: "Waves held offshore while the exits stay shut",
